import { readFileSync } from "node:fs";

const cache = new Map<string, string>();

export function summarize(text: string): string {
  const hit = cache.get(text);
  if (hit !== undefined) {
    return hit;
  }
  const summary = text.split(".")[0] ?? "";
  cache.set(text, summary);
  return summary;
}

